import{_ as r,o as i,c as l,a3 as t}from"./chunks/framework.BrO6lPIi.js";const u=JSON.parse('{"title":"Agent HTTP API","description":"未匹配路径或非 POST 业务方法返回 404，用于扩展探测旧版本 agent 是否支持记忆端点。","frontmatter":{"title":"Agent HTTP API","description":"未匹配路径或非 POST 业务方法返回 404，用于扩展探测旧版本 agent 是否支持记忆端点。"},"headers":[],"relativePath":"API-参考文档/Agent-HTTP-API/index.md","filePath":"API-参考文档/Agent-HTTP-API/index.md","lastUpdated":null}'),a={name:"API-参考文档/Agent-HTTP-API/index.md"};function o(c,e,s,n,g,d){return i(),l("div",null,[...e[0]||(e[0]=[t(`<h1 id="agent-http-api" tabindex="-1">Agent HTTP API <a class="header-anchor" href="#agent-http-api" aria-label="Permalink to &quot;Agent HTTP API&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js" target="_blank" rel="noreferrer">agent/src/auth.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js" target="_blank" rel="noreferrer">agent/src/security.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js" target="_blank" rel="noreferrer">agent/src/executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js" target="_blank" rel="noreferrer">agent/src/memory/routes.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js" target="_blank" rel="noreferrer">agent/src/rag/config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/directory-picker.js" target="_blank" rel="noreferrer">agent/src/directory-picker.js</a></li></ul></details><h2 id="更新摘要" tabindex="-1">更新摘要 <a class="header-anchor" href="#更新摘要" aria-label="Permalink to &quot;更新摘要&quot;">​</a></h2><p><strong>变更内容</strong></p><ul><li>新增 <code>/api/config/pick-directory</code> 端点，支持系统原生目录选择框</li><li>添加严格的回环地址访问验证，仅允许本机来源调用</li><li>实现跨平台原生对话框支持（macOS、Windows、Linux）</li><li>增加超时保护机制和错误降级处理</li></ul><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#简介">简介</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细接口规范">详细接口规范</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与限制">性能与限制</a></li><li><a href="#故障排除指南">故障排除指南</a></li><li><a href="#结论">结论</a></li></ol><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>Agent HTTP API 是 Chrome 扩展（Manifest V3）与独立本地代理端之间的通信契约。扩展通过本地 HTTP/WebSocket 调用 Agent 的文件操作、命令执行、长期记忆、RAG 检索、技能与 MCP 管理等能力。文档以版本 2.7.0 为准，所有端点、安全策略、错误格式和示例均基于当前源码实现。</p><p>关键运行时约束：</p><ul><li>Agent 为独立 Node.js 进程，修改源码后必须重启进程，新接口才生效。</li><li>认证采用 Bearer Token；首次配对使用一次性配对码流程。</li><li>路径访问受白名单与硬阻止规则保护；命令执行走黑白灰名单分级控制。</li><li>RAG 为可选依赖，不可用时对应接口返回 503。</li><li><strong>新增</strong>：原生目录选择功能仅限本机回环地址访问，确保安全性。</li></ul><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>Agent 端入口为 <code>agent/src/server.js</code>，负责 HTTP 路由、CORS、请求体解析、认证、日志、WebSocket 升级以及各子系统分发。核心子模块包括：</p><ul><li>认证：<code>agent/src/auth.js</code></li><li>安全策略：<code>agent/src/security.js</code></li><li>命令执行器：<code>agent/src/executor.js</code></li><li>记忆管理：<code>agent/src/memory/routes.js</code></li><li>RAG 配置：<code>agent/src/rag/config.js</code></li><li><strong>新增</strong>：原生目录选择器：<code>agent/src/directory-picker.js</code></li></ul><pre class="mermaid">graph TB
Client[&quot;客户端&lt;br/&gt;Chrome 扩展或本地脚本&quot;] --&gt; HTTP[&quot;HTTP 服务器&lt;br/&gt;server.js&quot;]
HTTP --&gt; Auth[&quot;认证模块&lt;br/&gt;auth.js&quot;]
HTTP --&gt; Security[&quot;安全策略&lt;br/&gt;security.js&quot;]
HTTP --&gt; Executor[&quot;命令执行器&lt;br/&gt;executor.js&quot;]
HTTP --&gt; Memory[&quot;记忆路由&lt;br/&gt;memory/routes.js&quot;]
HTTP --&gt; RAG[&quot;RAG 路由&lt;br/&gt;动态加载&quot;]
HTTP --&gt; DirectoryPicker[&quot;目录选择器&lt;br/&gt;directory-picker.js&quot;]
HTTP --&gt; WS[&quot;WebSocket 执行流&lt;br/&gt;server.js&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2086-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2086-L2153</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/directory-picker.js#L1-L135" target="_blank" rel="noreferrer">agent/src/directory-picker.js#L1-L135</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L65" target="_blank" rel="noreferrer">agent/src/server.js#L1-L65</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li><strong>HTTP 路由器</strong>：统一处理 CORS、JSON body、multipart、路径匹配、认证拦截、业务分发与 404。</li><li><strong>认证模块</strong>：维护配对码轮换、Token 验证、活跃连接窗口、失败锁定。</li><li><strong>安全策略</strong>：路径规范化、工作目录放行、白名单前缀校验、realpath 防符号链接绕过、硬阻止敏感目录；命令黑白灰名单分级。</li><li><strong>命令执行器</strong>：跨平台 shell 选择、子进程生命周期、超时预算、输出截断、WebSocket 广播、进程树终止。</li><li><strong>记忆路由</strong>：store/recall/inject/reindex 等记忆操作，embedding 配置与探活。</li><li><strong>RAG 配置</strong>：知识库根目录、集合注册表、模型缓存、默认 embedding 与分块参数。</li><li><strong>新增</strong>：<strong>原生目录选择器</strong>：跨平台系统对话框集成，包含超时保护和错误降级。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L250-L303" target="_blank" rel="noreferrer">agent/src/server.js#L250-L303</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L30-L127" target="_blank" rel="noreferrer">agent/src/auth.js#L30-L127</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L33-L229" target="_blank" rel="noreferrer">agent/src/security.js#L33-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L32-L91" target="_blank" rel="noreferrer">agent/src/executor.js#L32-L91</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L19-L27" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L19-L27</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L11-L54" target="_blank" rel="noreferrer">agent/src/rag/config.js#L11-L54</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/directory-picker.js#L1-L135" target="_blank" rel="noreferrer">agent/src/directory-picker.js#L1-L135</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>Agent 的认证与安全边界如下：</p><ul><li>无需认证的公开端点：<code>/api/pair</code>、<code>/api/status</code>、<code>/api/shutdown</code>（远程来源仍需认证）。</li><li>需要认证的端点：除上述公开端点外的绝大多数业务接口。</li><li>WebSocket <code>/ws/exec/{execId}</code>：支持 Authorization Header 或 query token。</li><li><strong>新增</strong>：<code>/api/config/pick-directory</code> 端点仅接受本机回环地址（127.0.0.1, ::1, localhost）请求。</li></ul><pre class="mermaid">sequenceDiagram
participant C as &quot;客户端&quot;
participant S as &quot;HTTP 服务器&quot;
participant A as &quot;认证模块&quot;
participant Sec as &quot;安全策略&quot;
participant DP as &quot;目录选择器&quot;
C-&gt;&gt;S : POST /api/pair {code, extensionId}
S-&gt;&gt;A : handlePairRequest(code, extensionId)
A--&gt;&gt;S : {success, token?}
S--&gt;&gt;C : 200/400 JSON
C-&gt;&gt;S : GET /api/status
S--&gt;&gt;C : 200 JSON(平台信息)
C-&gt;&gt;S : POST /api/fs/read {path}
S-&gt;&gt;Sec : checkPath(path)
Sec--&gt;&gt;S : {allowed,resolved}
S--&gt;&gt;C : 200/403/404 JSON
C-&gt;&gt;S : POST /api/exec {command,cwd,force,timeoutMs}
S-&gt;&gt;Sec : checkCommand(command, force)
Sec--&gt;&gt;S : {level : &#39;allow&#39;|&#39;confirm&#39;|&#39;deny&#39;}
alt level=deny
S--&gt;&gt;C : 403 JSON
else level=confirm
S--&gt;&gt;C : 200 JSON(level=confirm)
else level=allow
S-&gt;&gt;Ex : executeCommand(...)
S--&gt;&gt;C : 200 JSON(execId, wsUrl)
end
C-&gt;&gt;S : POST /api/config/pick-directory {title}
S-&gt;&gt;S : 验证回环地址
S-&gt;&gt;DP : pickDirectoryNative(title)
DP--&gt;&gt;S : {success, path, available}
S--&gt;&gt;C : 200 JSON
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L474-L548" target="_blank" rel="noreferrer">agent/src/server.js#L474-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1037-L1087" target="_blank" rel="noreferrer">agent/src/server.js#L1037-L1087</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1674" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1674</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L987-L1008" target="_blank" rel="noreferrer">agent/src/server.js#L987-L1008</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L138-L179" target="_blank" rel="noreferrer">agent/src/auth.js#L138-L179</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li></ul><h2 id="详细接口规范" tabindex="-1">详细接口规范 <a class="header-anchor" href="#详细接口规范" aria-label="Permalink to &quot;详细接口规范&quot;">​</a></h2><h3 id="通用约定" tabindex="-1">通用约定 <a class="header-anchor" href="#通用约定" aria-label="Permalink to &quot;通用约定&quot;">​</a></h3><ul><li>响应格式：<code>{ success: boolean, ... }</code>。成功时 <code>success=true</code>，失败时 <code>success=false</code> 且包含 <code>error</code>。</li><li>认证头：<code>Authorization: Bearer &lt;token&gt;</code>。</li><li>CORS：仅允许 <code>chrome-extension://</code> 来源读取响应；非浏览器客户端可忽略 CORS。</li><li>语言：通过 <code>Accept-Language</code> 影响错误消息文案。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L242-L266" target="_blank" rel="noreferrer">agent/src/server.js#L242-L266</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L427-L448" target="_blank" rel="noreferrer">agent/src/server.js#L427-L448</a></li></ul><h3 id="认证与配对" tabindex="-1">认证与配对 <a class="header-anchor" href="#认证与配对" aria-label="Permalink to &quot;认证与配对&quot;">​</a></h3><ul><li><code>POST /api/pair</code><ul><li>用途：输入 6 位配对码与扩展 ID，成功后返回 Token。</li><li>安全：连续失败 5 次锁定 60 秒并轮换配对码；配对成功后立即轮换。</li><li>响应：<code>{ success, token?, message?, error? }</code>。</li></ul></li><li><code>GET /api/status</code><ul><li>用途：健康检查与平台信息，无需认证。</li><li>响应：<code>{ success, version, running, platform, platformName, arch, nodeVersion, searchTools, ragAvailable }</code>。</li></ul></li><li><code>GET /api/status/detail</code><ul><li>用途：需认证的状态详情，含 workdir、allowedPaths、资源使用、运行进程等。</li><li>响应：<code>{ success, version, pairCodeTTL, workdir, allowedPaths, commandTimeout, fileMaxSize, uploadMaxSize, runningProcesses, resourceUsage, ...PLATFORM_INFO, searchTools, ragAvailable }</code>。</li></ul></li><li><code>GET /api/heartbeat</code><ul><li>用途：心跳保活，刷新最近认证时间。</li><li>响应：<code>{ success, time }</code>。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L30-L127" target="_blank" rel="noreferrer">agent/src/auth.js#L30-L127</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L138-L179" target="_blank" rel="noreferrer">agent/src/auth.js#L138-L179</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L474-L553" target="_blank" rel="noreferrer">agent/src/server.js#L474-L553</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L725-L749" target="_blank" rel="noreferrer">agent/src/server.js#L725-L749</a></li></ul><h3 id="配置管理-api-config" tabindex="-1">配置管理 <code>/api/config/*</code> <a class="header-anchor" href="#配置管理-api-config" aria-label="Permalink to &quot;配置管理 \`/api/config/*\`&quot;">​</a></h3><p>配置相关端点用于管理工作目录、白名单和系统设置。</p><ul><li><code>POST /api/config/workdir</code><ul><li>切换工作目录，同时追加到 allowedPaths（只增不减），禁止设为 Agent 系统目录。</li><li>响应：<code>{ success, workdir, allowedPaths, message }</code></li></ul></li><li><code>POST /api/config/allowed-paths/remove</code><ul><li>从 allowedPaths 移除路径，禁止移除当前工作目录。</li><li>响应：<code>{ success, allowedPaths, message? }</code></li></ul></li><li><strong>新增</strong> <code>POST /api/config/pick-directory</code><ul><li>用途：弹出系统原生目录选择框，用户可选择目标目录。</li><li><strong>安全限制</strong>：仅接受本机回环地址请求（127.0.0.1, ::1, ::ffff:127.0.0.1, localhost）。</li><li>请求体：<code>{ title?: string }</code> - 可选的选择框标题。</li><li>行为： <ul><li>远程来源：返回 <code>{ success: false, path: null, available: false, error: &#39;remote-source&#39; }</code></li><li>macOS：使用 <code>osascript choose folder</code> 对话框</li><li>Windows：使用 PowerShell FolderBrowserDialog</li><li>Linux：优先 zenity，回退 kdialog</li><li>无 GUI 环境：返回 <code>available: false</code></li><li>用户取消：返回 <code>{ success: true, path: null, available: true }</code></li><li>超时（120秒）：返回 <code>{ success: false, path: null, available: true, error: &#39;timeout&#39; }</code></li></ul></li><li>响应：<code>{ success, path, available, error? }</code></li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L872-L983" target="_blank" rel="noreferrer">agent/src/server.js#L872-L983</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L987-L1008" target="_blank" rel="noreferrer">agent/src/server.js#L987-L1008</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/directory-picker.js#L1-L135" target="_blank" rel="noreferrer">agent/src/directory-picker.js#L1-L135</a></li></ul><h3 id="文件操作-api-fs" tabindex="-1">文件操作 <code>/api/fs/*</code> <a class="header-anchor" href="#文件操作-api-fs" aria-label="Permalink to &quot;文件操作 \`/api/fs/*\`&quot;">​</a></h3><p>所有文件类接口均经过 <code>checkPath</code> 路径沙箱校验，遵循工作目录放行、白名单前缀、realpath 校验与硬阻止规则。</p><ul><li><code>POST /api/fs/search_files</code><ul><li>请求体：<code>{ path, pattern, recursive?, maxResults? }</code></li><li>响应：<code>{ success, path, pattern, total, engine, results? }</code></li></ul></li><li><code>POST /api/fs/search_content</code><ul><li>请求体：<code>{ path, pattern, filePattern?, caseSensitive?, recursive?, contextLines? }</code></li><li>响应：<code>{ success, path, pattern, total, engine, matches? }</code></li></ul></li><li><code>POST /api/fs/read</code><ul><li>请求体：<code>{ path }</code></li><li>响应：<code>{ success, content, size, path }</code></li></ul></li><li><code>POST /api/fs/write</code><ul><li>请求体：<code>{ path, content, encoding?: &#39;utf-8&#39;|&#39;base64&#39; }</code></li><li>行为：自动创建父目录；脚本文件写入后剥离执行权限。</li><li>响应：<code>{ success, size, path }</code></li></ul></li><li><code>POST /api/fs/list</code><ul><li>请求体：<code>{ path }</code></li><li>响应：<code>{ success, entries:[{name,type,size,mtime}], path }</code></li></ul></li><li><code>POST /api/fs/stat</code><ul><li>请求体：<code>{ path }</code></li><li>响应：<code>{ success, info:{name,path,type,size,mtime,ctime,atime,mode,isDirectory,isFile,isSymbolicLink,uid?,gid?,mimeType?} }</code></li></ul></li><li><code>POST /api/fs/delete</code><ul><li>请求体：<code>{ path }</code></li><li>行为：移至回收站，7 天后自动清理。</li><li>响应：<code>{ success, path, isDir, trashId, message }</code></li></ul></li><li><code>POST /api/fs/download</code><ul><li>请求体：<code>{ path }</code></li><li>行为：单文件 base64；目录打包 zip base64。</li><li>响应：<code>{ success, type:&#39;file&#39;|&#39;directory&#39;, name, size, content, mimeType }</code></li></ul></li><li><code>POST /api/fs/download-multi</code><ul><li>请求体：<code>{ paths:[string] }</code></li><li>行为：后端打包为 zip base64。</li><li>响应：<code>{ success, type:&#39;archive&#39;, name, size, content, mimeType }</code></li></ul></li><li><code>POST /api/fs/download-stream</code><ul><li>请求体：<code>{ path }</code> 或 <code>{ paths:[string] }</code></li><li>行为：二进制流下载，避免 base64 膨胀；目录打包 zip 流式返回。</li><li>响应：二进制流或 ZIP 附件。</li></ul></li><li><code>POST /api/fs/upload</code><ul><li>内容类型：<code>multipart/form-data</code></li><li>行为：文件名过滤危险字符，去重命名，写入工作目录。</li><li>响应：<code>{ success, path, name, size }</code></li></ul></li><li><code>POST /api/fs/upload-stream</code><ul><li>查询参数：<code>?path=&lt;目标路径&gt;</code></li><li>行为：原始二进制流上传，按 MAX_UPLOAD_SIZE 限制，脚本文件剥离执行权限。</li><li>响应：<code>{ success, size, path }</code></li></ul></li><li><code>POST /api/fs/mkdir</code><ul><li>请求体：<code>{ path }</code></li><li>响应：<code>{ success, path }</code></li></ul></li><li><code>POST /api/fs/rename</code><ul><li>请求体：<code>{ path, newName }</code></li><li>行为：仅改文件名不跨目录；Windows 非法字符校验；目标存在返回 409。</li><li>响应：<code>{ success, newPath, newName }</code></li></ul></li><li><code>POST /api/fs/move</code><ul><li>请求体：<code>{ path, destDir }</code></li><li>行为：源与目标均需白名单；目标不存在则创建；目标存在返回 409。</li><li>响应：<code>{ success, newPath }</code></li></ul></li><li><code>POST /api/fs/preview-xlsx</code><ul><li>请求体：<code>{ path }</code></li><li>行为：服务端解析前若干行，返回结构化 JSON。</li><li>响应：<code>{ success, data:{sheets:[{name,index,colCount,totalRows,rows}]}}</code></li></ul></li></ul><p>常见状态码：</p><ul><li>200：成功</li><li>400：参数缺失、大小超限、路径不是目录等</li><li>403：路径不在白名单或命中硬阻止</li><li>404：文件或目录不存在</li><li>409：目标已存在</li><li>500：内部错误</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L987-L1559" target="_blank" rel="noreferrer">agent/src/server.js#L987-L1559</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L752-L862" target="_blank" rel="noreferrer">agent/src/server.js#L752-L862</a></li></ul><h3 id="命令执行-api-exec" tabindex="-1">命令执行 <code>/api/exec/*</code> <a class="header-anchor" href="#命令执行-api-exec" aria-label="Permalink to &quot;命令执行 \`/api/exec/*\`&quot;">​</a></h3><p>命令执行先经 <code>checkCommand</code> 分级判定：</p><ul><li><p><code>deny</code>：黑名单命中，直接拒绝。</p></li><li><p><code>confirm</code>：灰名单命中，返回确认提示。</p></li><li><p><code>allow</code>：允许执行。</p></li><li><p><code>POST /api/exec</code></p><ul><li>请求体：<code>{ command, cwd?, wait?, force?, timeoutMs? }</code></li><li>行为： <ul><li><code>wait=true</code>：同步等待，返回完整 stdout/stderr。</li><li><code>wait=false</code>：异步执行，返回 <code>execId</code> 与 WebSocket URL。</li><li><code>force=true</code>：跳过灰名单（黑名单仍生效）。</li><li><code>timeoutMs</code>：受管模式协商超时预算。</li></ul></li><li>响应： <ul><li>同步：<code>{ success, level, execId, exitCode, stdout, stderr, killed, error? }</code></li><li>异步：<code>{ success, level, execId, wsUrl }</code></li></ul></li></ul></li><li><p><code>POST /api/exec/stop</code></p><ul><li>请求体：<code>{ execId }</code></li><li>响应：<code>{ success, execId }</code></li></ul></li><li><p><code>POST /api/exec/detach</code></p><ul><li>请求体：<code>{ execId }</code></li><li>行为：显式 daemon 化，豁免超时。</li><li>响应：<code>{ success, execId }</code></li></ul></li></ul><p>WebSocket <code>/ws/exec/{execId}</code>：</p><ul><li>认证：优先 <code>Authorization: Bearer &lt;token&gt;</code>，回退到 <code>?token=</code>。</li><li>消息类型：<code>stdout</code>、<code>stderr</code>、<code>exit</code>、<code>error</code>、<code>stdout_truncated</code>、<code>stderr_truncated</code>。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;收到 /api/exec&quot;]) --&gt; Validate[&quot;校验 command/cwd&quot;]
Validate --&gt; CheckCmd[&quot;checkCommand(command, force)&quot;]
CheckCmd --&gt; Level{&quot;level&quot;}
Level --&gt; |deny| Deny[&quot;返回 403 deny&quot;]
Level --&gt; |confirm| Confirm[&quot;返回 200 confirm&quot;]
Level --&gt; |allow| Mode{&quot;wait?&quot;}
Mode --&gt; |true| Sync[&quot;executeCommandSync&quot;]
Mode --&gt; |false| Async[&quot;executeCommand + 返回 wsUrl&quot;]
Sync --&gt; RespSync[&quot;返回 exitCode/stdout/stderr&quot;]
Async --&gt; WS[&quot;客户端连接 /ws/exec/{execId}&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1674" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1674</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1689" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1689</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L429-L493" target="_blank" rel="noreferrer">agent/src/executor.js#L429-L493</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li></ul><h3 id="记忆管理-api-memory" tabindex="-1">记忆管理 <code>/api/memory/*</code> <a class="header-anchor" href="#记忆管理-api-memory" aria-label="Permalink to &quot;记忆管理 \`/api/memory/*\`&quot;">​</a></h3><p>记忆路由由 <code>memoryRouter</code> 分发，支持 store/recall/inject/reindex 等业务动作，以及 embedding 配置与探活。</p><ul><li><code>POST /api/memory/embedding-config</code><ul><li>GET：返回掩码后的 embedding 配置。</li><li>POST：保存 embedding 配置。</li><li>响应：<code>{ success, config }</code></li></ul></li><li><code>POST /api/memory/test-embedding</code><ul><li>用途：测试 embedding provider 连通性。</li><li>响应：<code>{ success, dimensions }</code></li></ul></li><li><code>GET /api/memory/vector-status</code><ul><li>用途：向量缓存状态（条数、指纹陈旧等）。</li><li>响应：<code>{ success, ...vectorStatus }</code></li></ul></li><li><code>POST /api/memory/store</code><ul><li>请求体：记忆条目</li><li>行为：根据 <code>X-Memory-Caller</code> header 区分 user/model 来源。</li><li>响应：<code>{ success, ...storeResult }</code></li></ul></li><li><code>POST /api/memory/recall</code><ul><li>请求体：召回参数（可含 sessionId）</li><li>响应：<code>{ success, ...recallResult }</code></li></ul></li><li><code>POST /api/memory/inject</code><ul><li>行为：注入选择结果。</li><li>响应：<code>{ success, ...injectResult }</code></li></ul></li><li><code>POST /api/memory/reindex</code><ul><li>行为：重建向量缓存。</li><li>响应：<code>{ success, ...reindexResult }</code></li></ul></li></ul><p>未匹配路径或非 POST 业务方法返回 404，用于扩展探测旧版本 agent 是否支持记忆端点。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L19-L27" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L19-L27</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L77-L137" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L77-L137</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L149-L192" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L149-L192</a></li></ul><h3 id="rag-检索-api-rag" tabindex="-1">RAG 检索 <code>/api/rag/*</code> <a class="header-anchor" href="#rag-检索-api-rag" aria-label="Permalink to &quot;RAG 检索 \`/api/rag/*\`&quot;">​</a></h3><p>RAG 为可选依赖。依赖不可用时，除安装/检测相关端点外，其余 <code>/api/rag/*</code> 返回 503。</p><ul><li><code>POST /api/rag/install</code><ul><li>用途：启动 RAG 依赖安装任务。</li><li>响应：<code>{ started, ...installStatus }</code></li></ul></li><li><code>GET /api/rag/install/status</code><ul><li>用途：轮询安装进度。</li><li>响应：<code>{ ...installStatus }</code></li></ul></li><li><code>POST /api/rag/detect</code><ul><li>用途：重新检测 RAG 依赖可用性。</li><li>响应：<code>{ success, available, error? }</code></li></ul></li><li>其他 <code>/api/rag/*</code><ul><li>行为：依赖不可用返回 503；可用时动态加载 <code>rag/routes.js</code> 处理。</li></ul></li></ul><p>RAG 配置关键点：</p><ul><li>数据根目录：<code>~/.ai-helper-agent/rag</code>，可通过环境变量覆盖。</li><li>集合注册表：<code>collections.json</code>。</li><li>模型缓存：<code>models/</code>。</li><li>默认 embedding：本地 BGE 中文模型，支持 OpenAI 兼容模式。</li><li>分块参数：默认 chunkSize/overlap，单次批大小固定 10。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2025-L2067" target="_blank" rel="noreferrer">agent/src/server.js#L2025-L2067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L11-L54" target="_blank" rel="noreferrer">agent/src/rag/config.js#L11-L54</a></li></ul><h3 id="其他重要端点" tabindex="-1">其他重要端点 <a class="header-anchor" href="#其他重要端点" aria-label="Permalink to &quot;其他重要端点&quot;">​</a></h3><ul><li><code>POST /api/agent/restart</code><ul><li>重启 Agent，带冷却与互斥保护。</li><li>响应：<code>{ success, message }</code></li></ul></li><li><code>POST /api/agent/update</code><ul><li>更新并重启 Agent，与 RAG 安装互斥，npm 安装超时保护。</li><li>响应：<code>{ success, message }</code></li></ul></li><li><code>POST /api/shutdown</code><ul><li>本机来源免认证；远程来源需认证。</li><li>响应：<code>{ success, message }</code></li></ul></li><li><code>GET /api/trash/list</code><ul><li>列出回收站条目。</li><li>响应：<code>{ success, entries }</code></li></ul></li><li><code>POST /api/trash/restore</code><ul><li>恢复回收站条目。</li><li>响应：<code>{ success, restoredPath?, error? }</code></li></ul></li><li><code>GET /api/logs/query</code><ul><li>审计日志查询，默认最近 7 天，limit 上限 500。</li><li>响应：<code>{ success, entries, total, dates }</code></li></ul></li><li>Skill/MCP 管理端点：见 server.js 中 <code>/api/skill/*</code> 与 <code>/api/mcp/*</code> 路由。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L555-L720" target="_blank" rel="noreferrer">agent/src/server.js#L555-L720</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L502-L535" target="_blank" rel="noreferrer">agent/src/server.js#L502-L535</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2006-L2021" target="_blank" rel="noreferrer">agent/src/server.js#L2006-L2021</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1693-L1725" target="_blank" rel="noreferrer">agent/src/server.js#L1693-L1725</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><ul><li><code>server.js</code> 作为中心路由器，依赖： <ul><li><code>auth.js</code>：配对码与 Token 验证。</li><li><code>security.js</code>：路径与命令安全检查。</li><li><code>executor.js</code>：命令执行与 WebSocket 流。</li><li><code>memory/routes.js</code>：记忆业务分发。</li><li><code>rag/*</code>：按需加载 RAG 路由。</li><li><code>skill/*</code>、<code>mcp/*</code>：技能与 MCP 管理。</li><li><strong>新增</strong>：<code>directory-picker.js</code>：原生目录选择功能。</li></ul></li><li>安全边界： <ul><li>路径访问：workdir 永远放行，allowedPaths 前缀匹配，realpath 防绕过，硬阻止 Agent 敏感目录。</li><li>命令执行：黑名单绝对禁止，灰名单需确认，force 可跳过灰名单。</li><li>文件大小：JSON body 最大 200MB；流式上传最大 200MB；读取默认 50MB。</li><li><strong>新增</strong>：目录选择仅允许本机回环地址访问。</li></ul></li></ul><pre class="mermaid">graph LR
Server[&quot;server.js&quot;] --&gt; Auth[&quot;auth.js&quot;]
Server --&gt; Security[&quot;security.js&quot;]
Server --&gt; Executor[&quot;executor.js&quot;]
Server --&gt; Memory[&quot;memory/routes.js&quot;]
Server --&gt; RAG[&quot;rag/routes.js(动态)&quot;]
Server --&gt; Skill[&quot;skill/*&quot;]
Server --&gt; MCP[&quot;mcp/*&quot;]
Server --&gt; DirectoryPicker[&quot;directory-picker.js&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L13-L56" target="_blank" rel="noreferrer">agent/src/server.js#L13-L56</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2051-L2072" target="_blank" rel="noreferrer">agent/src/server.js#L2051-L2072</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L57" target="_blank" rel="noreferrer">agent/src/server.js#L57</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L13-L56" target="_blank" rel="noreferrer">agent/src/server.js#L13-L56</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L62-L100" target="_blank" rel="noreferrer">agent/src/security.js#L62-L100</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L285-L384" target="_blank" rel="noreferrer">agent/src/security.js#L285-L384</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/directory-picker.js#L1-L135" target="_blank" rel="noreferrer">agent/src/directory-picker.js#L1-L135</a></li></ul><h2 id="性能与限制" tabindex="-1">性能与限制 <a class="header-anchor" href="#性能与限制" aria-label="Permalink to &quot;性能与限制&quot;">​</a></h2><ul><li>请求体大小：MAX_BODY_SIZE = 200MB。</li><li>文件读取默认限制：DEFAULT_MAX_SIZE = 50MB，可通过配置调整。</li><li>流式上传限制：MAX_UPLOAD_SIZE = 200MB。</li><li>搜索最大结果：MAX_SEARCH_RESULTS = 5000。</li><li>命令输出缓冲：MAX_OUTPUT_BUFFER = 5MB，超限时广播 truncated 事件。</li><li>命令超时策略：受管模式下按输出心跳延长，最多延长次数与总预算封顶。</li><li>RAG 批大小：EMBED_BATCH_SIZE = 10。</li><li><strong>新增</strong>：目录选择超时：PICK_TIMEOUT_MS = 120秒。</li></ul><p>优化建议：</p><ul><li>大文件下载优先使用 <code>/api/fs/download-stream</code>。</li><li>长命令使用异步模式 + WebSocket 实时查看输出。</li><li>合理设置 <code>timeoutMs</code>，避免静默挂起导致频繁延长。</li><li>目录选择仅在本地开发环境中使用，生产环境应通过配置文件设置工作目录。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L132-L136" target="_blank" rel="noreferrer">agent/src/server.js#L132-L136</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L96-L98" target="_blank" rel="noreferrer">agent/src/executor.js#L96-L98</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L166-L186" target="_blank" rel="noreferrer">agent/src/executor.js#L166-L186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L52-L54" target="_blank" rel="noreferrer">agent/src/rag/config.js#L52-L54</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/directory-picker.js#L7" target="_blank" rel="noreferrer">agent/src/directory-picker.js#L7</a></li></ul><h2 id="故障排除指南" tabindex="-1">故障排除指南 <a class="header-anchor" href="#故障排除指南" aria-label="Permalink to &quot;故障排除指南&quot;">​</a></h2><p>常见问题与定位：</p><ul><li>401/403：认证缺失或 Token 无效。检查 <code>Authorization</code> 头与配对流程。</li><li>403 路径拒绝：路径不在 allowedPaths 或命中硬阻止。检查工作目录与白名单配置。</li><li>403 命令拒绝：命令命中黑名单。无法通过 force 绕过。</li><li>200 confirm：命令命中灰名单。前端应弹出确认框后再调用 <code>force=true</code>。</li><li>503 RAG 不可用：RAG 依赖未安装或检测失败。调用 <code>/api/rag/install</code> 与 <code>/api/rag/detect</code>。</li><li>500 内部错误：查看审计日志 <code>/api/logs/query</code>，关注 category 为 system/error 的条目。</li><li>命令无输出：检查 WebSocket 是否连接成功，或查看 <code>/api/exec</code> 返回的 <code>wsUrl</code>。</li><li>文件过大：read/download 受 DEFAULT_MAX_SIZE 限制；使用 stream 接口或调整配置。</li><li><strong>新增</strong>：目录选择不可用：检查是否为本机回环地址访问，或系统是否安装了必要的 GUI 工具（zenity/kdialog/osascript）。</li><li><strong>新增</strong>：目录选择超时：用户长时间未选择，120秒后自动超时。</li></ul><p>调试步骤：</p><ol><li>调用 <code>/api/status</code> 确认 Agent 在线与版本。</li><li>调用 <code>/api/status/detail</code> 查看 workdir、allowedPaths、runningProcesses。</li><li>使用 <code>/api/logs/query</code> 查询最近日志，过滤 category。</li><li>对文件操作，先用 <code>/api/fs/stat</code> 确认路径存在与类型。</li><li>对命令执行，先调 <code>/api/exec</code> 获取 level，再决定是否确认或调整命令。</li><li><strong>新增</strong>：对目录选择，检查请求来源 IP 是否为回环地址，并确认系统 GUI 环境可用。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L474-L548" target="_blank" rel="noreferrer">agent/src/server.js#L474-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1037-L1087" target="_blank" rel="noreferrer">agent/src/server.js#L1037-L1087</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1674" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1674</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2025-L2067" target="_blank" rel="noreferrer">agent/src/server.js#L2025-L2067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1705-L1725" target="_blank" rel="noreferrer">agent/src/server.js#L1705-L1725</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L987-L1008" target="_blank" rel="noreferrer">agent/src/server.js#L987-L1008</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>Agent HTTP API 提供完整的本地代理能力，涵盖文件、命令、记忆、RAG、技能与 MCP。其安全模型以路径白名单与命令分级为核心，认证采用配对码+Bearer Token，WebSocket 支持命令流式输出。<strong>新增的原生目录选择功能</strong>进一步增强了用户体验，但严格限制了访问来源以确保安全性。使用时应严格遵循认证头、路径白名单、大小限制与超时策略，并结合审计日志进行故障定位。对于目录选择功能，应特别注意其仅限本机回环地址访问的安全限制。</p>`,99)])])}const p=r(a,[["render",o]]);export{u as __pageData,p as default};
